SUMMARY_BLOB = '26f16c0edc7a7447b54412ecf7e1c79cac5e304c'

def pinned(path, expected):
    data = (ROOT / path).read_bytes()
    actual = hashlib.sha1(b'blob ' + str(len(data)).encode() + b'\0' + data).hexdigest()
    if actual != expected:
        raise ValueError(f'Pinned source changed: {path}. Review a new snapshot before rebuilding.')
    return data

